// final class ListNode { var val: Int; var next: ListNode?; init(_ v: Int, _ n: ListNode? = nil) { val = v; next = n } }
func reorderList(_ head: ListNode?) {
    guard let head else { return }
    var slow = head, fast = head
    while let next = fast.next?.next { slow = slow.next!; fast = next }
    var second = slow.next, prev: ListNode? = nil
    slow.next = nil
    while let node = second { second = node.next; node.next = prev; prev = node }
    var first: ListNode? = head, back = prev
    while let f = first, let b = back {
        let fNext = f.next, bNext = b.next
        f.next = b; b.next = fNext
        first = fNext; back = bNext
    }
}
